//! Stride-aware parallel splitting for LDA evaluations.
//!
//! GENERATED by tools/translate_rayon/gen_eval.py -- do not hand-edit.
//!
//! Each array carries its own elements-per-grid-point count (`Dimensions`), so
//! a run of `n` grid points sits at a *different* offset in every array.
//! Splitting them all at one offset compiles fine and silently misaligns every
//! output past the first chunk, so each is split at its own stride.
//!
//! The split is recursive halving through `rayon::join`, which keeps it in safe
//! code: each worker gets genuinely disjoint `&mut` slices, with no raw
//! pointers anywhere.

use libxc_core::dims::Dimensions;

use crate::screen::{Screen, m_max};

/// One contiguous run of grid points, every array narrowed to it.
pub struct LdaChunk<'inp, 'out> {
    pub np: usize,
    pub rho: &'inp [f64],
    pub zk: Option<&'out mut [f64]>,
    pub vrho: Option<&'out mut [f64]>,
    pub v2rho2: Option<&'out mut [f64]>,
    pub v3rho3: Option<&'out mut [f64]>,
    pub v4rho4: Option<&'out mut [f64]>,
}

#[inline]
fn split_opt<'out>(o: Option<&'out mut [f64]>, at: usize) -> (Option<&'out mut [f64]>, Option<&'out mut [f64]>) {
    match o {
        Some(s) => {
            let (l, r) = s.split_at_mut(at);
            (Some(l), Some(r))
        }
        None => (None, None),
    }
}

impl<'inp, 'out> LdaChunk<'inp, 'out> {
    /// Split at grid point `mid`, narrowing every array at its own stride.
    pub fn split_at(self, mid: usize, d: &Dimensions) -> (LdaChunk<'inp, 'out>, LdaChunk<'inp, 'out>) {
        let (rho_l, rho_r) = self.rho.split_at(mid * d.rho as usize);
        let (o0_l, o0_r) = split_opt(self.zk, mid * d.zk as usize);
        let (o1_l, o1_r) = split_opt(self.vrho, mid * d.vrho as usize);
        let (o2_l, o2_r) = split_opt(self.v2rho2, mid * d.v2rho2 as usize);
        let (o3_l, o3_r) = split_opt(self.v3rho3, mid * d.v3rho3 as usize);
        let (o4_l, o4_r) = split_opt(self.v4rho4, mid * d.v4rho4 as usize);
        (
            LdaChunk {
                np: mid,
                rho: rho_l,
                zk: o0_l,
                vrho: o1_l,
                v2rho2: o2_l,
                v3rho3: o3_l,
                v4rho4: o4_l,
            },
            LdaChunk {
                np: self.np - mid,
                rho: rho_r,
                zk: o0_r,
                vrho: o1_r,
                v2rho2: o2_r,
                v3rho3: o3_r,
                v4rho4: o4_r,
            },
        )
    }

    /// Reborrow a contiguous window of `len` grid points starting at `start`.
    ///
    /// `split_at` consumes the chunk, which is what the halving sweep wants but
    /// not what density screening wants: there the same chunk has to be visited
    /// as several disjoint windows and then still be available to clean up
    /// afterwards. Reborrowing keeps ownership with the caller. Every array is
    /// narrowed at its own stride, for the same reason `split_at` is.
    fn window(&mut self, start: usize, len: usize, d: &Dimensions) -> LdaChunk<'inp, '_> {
        let end = start + len;
        LdaChunk {
            np: len,
            rho: &self.rho[start * d.rho as usize..end * d.rho as usize],
            zk: self.zk.as_deref_mut()
                .map(|s| &mut s[start * d.zk as usize..end * d.zk as usize]),
            vrho: self.vrho.as_deref_mut()
                .map(|s| &mut s[start * d.vrho as usize..end * d.vrho as usize]),
            v2rho2: self.v2rho2.as_deref_mut()
                .map(|s| &mut s[start * d.v2rho2 as usize..end * d.v2rho2 as usize]),
            v3rho3: self.v3rho3.as_deref_mut()
                .map(|s| &mut s[start * d.v3rho3 as usize..end * d.v3rho3 as usize]),
            v4rho4: self.v4rho4.as_deref_mut()
                .map(|s| &mut s[start * d.v4rho4 as usize..end * d.v4rho4 as usize]),
        }
    }
}

use std::sync::atomic::{AtomicUsize, Ordering};

/// Minimum grid points per task; below this, splitting costs more than it saves.
static MIN_CHUNK: AtomicUsize = AtomicUsize::new(2048);

pub fn min_chunk() -> usize {
    MIN_CHUNK.load(Ordering::Relaxed)
}

/// Test hook. Setting this to `usize::MAX` disables splitting, so a dispatch
/// runs as one whole-grid call -- which is exactly the reference the chunked
/// path has to reproduce bit-for-bit.
pub fn set_min_chunk(n: usize) {
    MIN_CHUNK.store(n.max(1), Ordering::Relaxed);
}

/// Clear this chunk's slice of every output the sweep is going to write.
///
/// The kernels accumulate with `+=`, so the destination has to start at zero.
/// Doing that in `prepare` instead -- one `fill(0.0)` per whole output array --
/// costs a full serial pass over every output buffer before any arithmetic
/// starts, and leaves the memory cold: by the time the kernel accumulates into
/// a given cache line, the zero written into it has long been evicted, so each
/// element is fetched from DRAM a second time. Per chunk, the zeroed range is
/// still in L1/L2 when the kernel reads it back, and the clearing itself is
/// spread over every worker instead of running on one thread.
///
/// Bit-exactness is unaffected: the stored value and the order of the
/// accumulations are identical either way, only the moment of the store moves.
#[inline]
fn zero_outputs(chunk: &mut LdaChunk<'_, '_>) {
    if let Some(s) = chunk.zk.as_deref_mut() { s.fill(0.0); }
    if let Some(s) = chunk.vrho.as_deref_mut() { s.fill(0.0); }
    if let Some(s) = chunk.v2rho2.as_deref_mut() { s.fill(0.0); }
    if let Some(s) = chunk.v3rho3.as_deref_mut() { s.fill(0.0); }
    if let Some(s) = chunk.v4rho4.as_deref_mut() { s.fill(0.0); }
}

/// Total density at grid point `ip`, the quantity libxc screens on.
#[inline]
fn total_density(rho: &[f64], ip: usize, nc: usize) -> f64 {
    if nc == 1 { rho[ip] } else { rho[ip * 2] + rho[ip * 2 + 1] }
}

/// Clear every output at one grid point.
#[inline]
fn zero_point(chunk: &mut LdaChunk<'_, '_>, ip: usize, d: &Dimensions) {
    if let Some(s) = chunk.zk.as_deref_mut() {
        let w = d.zk as usize;
        s[ip * w..(ip + 1) * w].fill(0.0);
    }
    if let Some(s) = chunk.vrho.as_deref_mut() {
        let w = d.vrho as usize;
        s[ip * w..(ip + 1) * w].fill(0.0);
    }
    if let Some(s) = chunk.v2rho2.as_deref_mut() {
        let w = d.v2rho2 as usize;
        s[ip * w..(ip + 1) * w].fill(0.0);
    }
    if let Some(s) = chunk.v3rho3.as_deref_mut() {
        let w = d.v3rho3 as usize;
        s[ip * w..(ip + 1) * w].fill(0.0);
    }
    if let Some(s) = chunk.v4rho4.as_deref_mut() {
        let w = d.v4rho4 as usize;
        s[ip * w..(ip + 1) * w].fill(0.0);
    }
}


// ---------------------------------------------------------------------------
// libxc's input sanitisation (`work_lda_inc.c`), and the fast path past it.
// ---------------------------------------------------------------------------

thread_local! {
    /// Per-worker scratch for sanitised inputs.
    ///
    /// A leaf is at most `min_chunk` points, so this settles at a few tens of
    /// kB per rayon worker and is never reallocated after the first chunk that
    /// needs it. It is *taken* out of the cell for the duration of the call
    /// rather than borrowed across it, so a nested evaluation on the same
    /// worker -- a composite dispatching one of its auxiliaries -- gets its
    /// own buffer instead of panicking on a double borrow.
    static SANITISED: std::cell::Cell<Vec<f64>> = const { std::cell::Cell::new(Vec::new()) };
}

/// One grid point's inputs, clamped exactly as `work_lda_inc.c` clamps them.
///
/// Component `i` of each returned array is meaningful only for `i < nc` (rho,
/// tau) or `i < ns` (sigma). libxc leaves the rest at the `0.0` its stack
/// arrays were initialised with and the unpolarized kernels never read them.
#[inline(always)]
fn sanitise_point(rho: &[f64], ip: usize, nc: usize, sc: &Screen) -> [f64; 2] {
    let mut r = [0.0f64; 2];
    r[0] = m_max(sc.dens, rho[ip * nc]);
    if nc == 2 {
        r[1] = m_max(sc.dens, rho[ip * nc + 1]);
    }
    r
}

/// Does any point the kernel will actually see carry an input libxc would
/// clamp?
///
/// The clamps are the identity on a physical quadrature: `sigma_ab` really is
/// bounded by `(sigma_aa + sigma_bb)/2`, `tau` really does satisfy the von
/// Weizsaecker bound `sigma <= 8 rho tau`, and the screen has already
/// established `rho >= dens_threshold` for the total density. So this pass
/// almost always answers no and the kernel then runs on the caller's own
/// slices with no copy at all. It answers yes on the randomised grids the
/// oracle and bench harnesses build, and at polarized points where one spin
/// channel is empty.
///
/// The predicate *is* the transform: it runs [`sanitise_point`] and compares
/// the result bit for bit, so it cannot drift out of agreement with what
/// [`sanitise_into`] would write.
///
/// Below-threshold points are skipped. Their outputs are zero either way, and
/// a molecular grid's empty tail would otherwise force the copy on every chunk
/// that reaches into it.
fn needs_sanitise(chunk: &LdaChunk<'_, '_>, d: &Dimensions, sc: &Screen) -> bool {
    let nc = d.rho as usize;
    for ip in 0..chunk.np {
        if total_density(chunk.rho, ip, nc) < sc.dens {
            continue;
        }
        let r = sanitise_point(chunk.rho, ip, nc, sc);
        for c in 0..nc {
            if r[c].to_bits() != chunk.rho[ip * nc + c].to_bits() {
                return true;
            }
        }
    }
    false
}

/// Write the whole chunk's sanitised inputs into `buf`, one flat run per
/// array.
///
/// Below-threshold points are clamped too, rather than skipped: the
/// fragmented-grid route runs the kernel over them and zeroes their outputs
/// afterwards, and clamped inputs are strictly better behaved there.
fn sanitise_into(buf: &mut Vec<f64>, chunk: &LdaChunk<'_, '_>, d: &Dimensions, sc: &Screen) {
    let nc = d.rho as usize;
    let np = chunk.np;
    buf.clear();
    buf.resize(np * nc, 0.0);

    for ip in 0..np {
        let r = sanitise_point(chunk.rho, ip, nc, sc);
        for c in 0..nc {
            buf[ip * nc + c] = r[c];
        }
    }
}

/// The same chunk with its input arrays pointed at sanitised copies. The
/// outputs move across untouched -- they are still the caller's buffers.
fn retarget<'i, 's, 'o>(c: LdaChunk<'i, 'o>, rho: &'s [f64]) -> LdaChunk<'s, 'o>
where
    'i: 's,
{
    LdaChunk {
        np: c.np,
        rho,
        zk: c.zk,
        vrho: c.vrho,
        v2rho2: c.v2rho2,
        v3rho3: c.v3rho3,
        v4rho4: c.v4rho4,
    }
}

/// Average length an above-threshold run must reach before it is worth calling
/// the kernel on it separately.
///
/// Splitting has a fixed per-call cost (the kernel's prologue, and the loop
/// never getting up to speed). Measured on this tree, splitting a grid whose
/// below-threshold points are scattered individually -- average run ~1.7 points
/// -- cost about 14 ns per call, which turned `gga_x_b88` from 1.98 to 6.84
/// ns/point: worse than doing no screening at all. So a fragmented chunk takes
/// the other route below instead.
const MIN_RUN: usize = 128;

/// Evaluate `f` over the above-threshold points only, leaving the rest zero.
///
/// This reproduces what libxc does at the top of its per-point loop
/// (`work_lda_inc.c`):
///
/// ```c
/// dens = (nspin == XC_POLARIZED) ? rho[2*ip] + rho[2*ip+1] : rho[ip];
/// if(dens < p->dens_threshold)
///   continue;
/// ```
///
/// **It is a correctness fix before it is an optimisation.** Only some kernels
/// carry a `dens_threshold` guard of their own -- the exchange functionals
/// mostly do (`gga_x_b88`: `rho[ip] / 2.0 <= dens_threshold`), the correlation
/// functionals mostly do not (`lda_c_vwn`, `gga_c_lyp`, `mgga_c_r2scan` have
/// none). libxc puts the screen *outside* the maple2c body, so it covers all of
/// them uniformly; this library called the body directly, so for an unguarded
/// functional the empty tail of a molecular grid got the raw formula value
/// where libxc gives exactly 0. Measured against C libxc on a grid with 40% of
/// its points below threshold, `lda_c_vwn` and `gga_c_lyp` came back with a
/// worst relative difference of 1.0 -- a 100% error on `zk` -- while
/// `gga_x_b88` and `mgga_x_scan`, which have the guard, agreed to 1e-15.
///
/// For a screened point the output keeps the zero `zero_outputs` just wrote.
/// That is bit-identical to what a *guarded* kernel would have produced there
/// (its outputs are `piecewise3(guard, 0.0, ..)` terms, which collapse to
/// `+0.0`), so this changes nothing for those functionals and fixes the rest.
/// Verified: with no below-threshold points present, every output fingerprint
/// is unchanged by this function existing.
///
/// Two routes, picked from a single forward pass over `rho`:
///
/// * **Runs.** A real Becke/Lebedev grid orders points by radial shell, so its
///   empty points are contiguous. Each maximal above-threshold run becomes one
///   kernel call and the tail is never touched -- a whole empty chunk costs
///   nothing at all.
/// * **Compute then re-zero.** If the below-threshold points are scattered so
///   finely that runs would average under `MIN_RUN`, splitting costs more than
///   it saves. Then the kernel runs over the whole chunk and the screened
///   points are zeroed afterwards. No arithmetic is saved, but the answer is
///   the same one, which is the part that matters.
fn screened_call<F>(chunk: LdaChunk<'_, '_>, d: &Dimensions, sc: &Screen, f: &F)
where
    F: Fn(&mut LdaChunk<'_, '_>) + Sync,
{
    let nc = d.rho as usize;
    let np = chunk.np;

    // One pass: how many points are screened out, and into how many runs do the
    // survivors fall.
    let mut below = 0usize;
    let mut runs = 0usize;
    let mut prev_active = false;
    for ip in 0..np {
        let active = total_density(chunk.rho, ip, nc) >= sc.dens;
        if !active {
            below += 1;
        } else if !prev_active {
            runs += 1;
        }
        prev_active = active;
    }

    // Whole chunk is in the tail: the zeros already written are the answer, and
    // there is nothing left to sanitise for.
    if below == np {
        return;
    }

    // Second half of what libxc does before the maple2c body runs: clamp the
    // inputs it is about to use (`crate::screen`). Almost always a no-op, and
    // then the kernel reads the caller's slices directly.
    if !needs_sanitise(&chunk, d, sc) {
        run_screened(chunk, d, sc.dens, below, runs, f);
        return;
    }

    let raw_rho = chunk.rho;
    let mut buf = SANITISED.with(|c| c.take());
    sanitise_into(&mut buf, &chunk, d, sc);
    {
        let (rho_s, rest) = buf.split_at(np * nc);
        debug_assert!(rest.is_empty());
        let c2 = retarget(chunk, rho_s);
        // The screen still reads the *caller's* rho: every sanitised rho is at
        // least `dens_threshold` by construction, so screening on it would
        // admit the whole tail.
        run_screened_with(c2, raw_rho, d, sc.dens, below, runs, f);
    }
    SANITISED.with(|c| c.set(buf));
}

/// [`screened_call`]'s second half for a chunk whose inputs did not need
/// clamping, so the density screen can read the chunk's own `rho`.
fn run_screened<F>(chunk: LdaChunk<'_, '_>, d: &Dimensions, dens_threshold: f64, below: usize, runs: usize, f: &F)
where
    F: Fn(&mut LdaChunk<'_, '_>) + Sync,
{
    // Reborrowing `rho` here and passing it back in is what lets the sanitised
    // path share this code: there the screen has to read a different array
    // from the one the kernel does.
    let rho = chunk.rho;
    run_screened_with(chunk, rho, d, dens_threshold, below, runs, f);
}

/// Run `f` over the above-threshold points of `chunk`, screening on `raw_rho`.
///
/// `raw_rho` is the density the *caller* passed, which is the only one libxc's
/// `if(dens < p->dens_threshold) continue;` ever sees. It is a separate
/// argument because `chunk.rho` may by now be the clamped copy, in which case
/// every point would test as above-threshold.
fn run_screened_with<F>(
    mut chunk: LdaChunk<'_, '_>,
    raw_rho: &[f64],
    d: &Dimensions,
    dens_threshold: f64,
    below: usize,
    runs: usize,
    f: &F,
) where
    F: Fn(&mut LdaChunk<'_, '_>) + Sync,
{
    let nc = d.rho as usize;
    let np = chunk.np;

    // Overwhelmingly the common case: nothing to screen.
    if below == 0 {
        f(&mut chunk);
        return;
    }
    if below == np {
        return;
    }

    if runs * MIN_RUN <= np - below {
        let mut ip = 0;
        while ip < np {
            if total_density(raw_rho, ip, nc) < dens_threshold {
                ip += 1;
                continue;
            }
            let start = ip;
            while ip < np && total_density(raw_rho, ip, nc) >= dens_threshold {
                ip += 1;
            }
            let mut w = chunk.window(start, ip - start, d);
            f(&mut w);
        }
    } else {
        f(&mut chunk);
        for ip in 0..np {
            if total_density(raw_rho, ip, nc) < dens_threshold {
                zero_point(&mut chunk, ip, d);
            }
        }
    }
}

/// Recursively halve the grid and evaluate each piece in parallel.
pub fn par_sweep<F>(
    mut chunk: LdaChunk<'_, '_>,
    d: &Dimensions,
    min_chunk: usize,
    sc: &Screen,
    f: &F,
) where
    F: Fn(&mut LdaChunk<'_, '_>) + Sync,
{
    if chunk.np <= min_chunk {
        zero_outputs(&mut chunk);
        screened_call(chunk, d, sc, f);
        return;
    }
    let mid = chunk.np / 2;
    let (l, r) = chunk.split_at(mid, d);
    rayon::join(
        || par_sweep(l, d, min_chunk, sc, f),
        || par_sweep(r, d, min_chunk, sc, f),
    );
}

/// Recursively halve the grid and hand every leaf to `f`, in parallel.
///
/// The same split as [`par_sweep`] -- every array narrowed at its own stride,
/// leaves of at most `min_chunk` points -- but with nothing done to the leaf:
/// no zeroing, no density screening. It exists for the composite (mixed)
/// path in `libxc-eval`, which runs several auxiliary kernels over each leaf
/// and accumulates them into the parent's outputs while the leaf is still in
/// cache. Each auxiliary is dispatched as an ordinary whole-"grid" call over
/// the leaf, so it gets its own zeroing and its own screening from
/// [`par_sweep`] exactly as it would on the full grid; and because a leaf is
/// already at most `min_chunk` points, that inner call never splits again.
pub fn par_leaves<F>(chunk: LdaChunk<'_, '_>, d: &Dimensions, min_chunk: usize, f: &F)
where
    F: Fn(&mut LdaChunk<'_, '_>) + Sync,
{
    if chunk.np <= min_chunk {
        let mut leaf = chunk;
        f(&mut leaf);
        return;
    }
    let mid = chunk.np / 2;
    let (l, r) = chunk.split_at(mid, d);
    rayon::join(|| par_leaves(l, d, min_chunk, f), || par_leaves(r, d, min_chunk, f));
}
